const LLMS_TXT_CONTENT = "# ImgOF\n\n> Free, ultrafast, serverless image hosting and CDN delivery API powered by Cloudflare Workers and Google Drive.\n\n## Documentation\n- [API Documentation](https://imgof.my.id/docs): Complete REST API documentation for upload, delete, and metadata retrieval.\n- [Frequently Asked Questions](https://imgof.my.id/faq): Storage limits, retention policies, and supported image formats.\n- [Terms of Service & Privacy Policy](https://imgof.my.id/legal): User terms, acceptable use policy, and DMCA takedown procedures.\n- [ShareX Configuration](https://imgof.my.id/sharex.sxcu): Downloadable configuration file for ShareX desktop integration.\n\n## API Endpoints\n- [Upload File Endpoint](https://imgof.my.id/api/upload): POST endpoint for binary image file upload via multipart/form-data.\n- [Remote URL Upload Endpoint](https://imgof.my.id/api/upload): POST endpoint for importing remote image URLs via JSON payload.\n- [Image Metadata Endpoint](https://imgof.my.id/api/info): GET endpoint for viewing image stats, mime type, and dimensions.\n- [Delete Image Endpoint](https://imgof.my.id/api/delete): DELETE endpoint for permanently removing images via delete token.\n";

const CANARY_URL = 'https://canarytokens.com/about/terms/5uvajs7m7k9di88n65sz8oic0/submit.aspx';

const createHtmlResponse = (content: string) => {
    return new Response(content, {
        headers: {
            'Content-Type': 'text/html; charset=UTF-8',
            'Cache-Control': 'public, max-age=3600, s-maxage=86400, stale-while-revalidate=86400'
        }
    });
};

// 1. Robots.txt with Honeypot Decoys
frontendRoute.get('/robots.txt', (c) => {
    const robots = [
        'User-agent: *',
        'Allow: /',
        'Disallow: /api/',
        'Disallow: /admin-login',
        'Disallow: /internal-backup',
        'Disallow: /admin-secret',
        'Disallow: /.env',
        'Sitemap: ' + new URL(c.req.url).origin + '/sitemap.xml'
    ].join('\n');
    return new Response(robots, {
        headers: {
            'Content-Type': 'text/plain; charset=UTF-8',
            'Cache-Control': 'public, max-age=86400'
        }
    });
});

// llms.txt Standard Endpoint for AI agents (llmstxt.org)
frontendRoute.get('/llms.txt', (c) => {
    return new Response(LLMS_TXT_CONTENT, {
        headers: {
            'Content-Type': 'text/plain; charset=UTF-8',
            'Cache-Control': 'public, max-age=86400, stale-while-revalidate=604800'
        }
    });
});

frontendRoute.get('/sitemap.xml', function(c) {
    var origin = new URL(c.req.url).origin;
    var pages = ['', '/legal', '/faq', '/docs', '/contact', '/status', '/stats', '/my'];
    var now = new Date().toISOString();
    var urls = pages.map(function(p) { return '  <url><loc>' + origin + (p || '/') + '</loc><lastmod>' + now + '</lastmod></url>'; }).join(String.fromCharCode(10));
    var xml = '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + String.fromCharCode(10) + urls + String.fromCharCode(10) + '</urlset>';
    return new Response(xml, { headers: { 'Content-Type': 'application/xml; charset=UTF-8', 'Cache-Control': 'public, max-age=86400' } });
});

// 2. Honeypot Trigger Handler
const handleHoneypot = async (c: any) => {
    const clientIp = c.req.header('CF-Connecting-IP') || c.req.header('X-Forwarded-For') || 'unknown';
    const userAgent = c.req.header('User-Agent') || 'unknown';

    // Trigger Canary Token in background with attacker context
    if (c.executionCtx && c.executionCtx.waitUntil) {
        c.executionCtx.waitUntil(
            fetch(CANARY_URL, {
                headers: {
                    'User-Agent': `${userAgent} (Honeypot Trap at ${c.req.path} by ${clientIp})`,
                    'X-Forwarded-For': clientIp
                }
            }).catch(() => {})
        );
    }

    return c.json({
        success: false,
        error: 'Forbidden: Access to restricted area logged.'
    }, 403);
};

// Decoy Honeypot Routes
